     values ('9531985d-5d9d-49f8-9818-e811892f902b', '6513270e-269e-4d37-b2a7-4de452e6b438', 'autumn-meetup', 'Autumn Design Meetup: Registration', 'Two days of talks, workshops and a riverside social, October 16 to 17 in Lisbon. Save your spot below.', true, '#0f766e', 'You''re on the list! We''ll email your ticket a week before the meetup.', true);



